import React, { useEffect, useState } from "react";
import {
  LineChart, Line, XAxis, YAxis, Tooltip, ResponsiveContainer
} from "recharts";

export const getTransactions = async () => {
  try {
    const response = await fetch("http://localhost:8000/transactions"); // FastAPI endpoint'iniz
    if (!response.ok) {
      throw new Error("Veri çekilemedi!");
    }
    const data = await response.json();
    return { data };
  } catch (error) {
    console.error("API Hatası:", error);
    return { data: [] };
  }
};

export const getUserStatus = async (id) => {
  try {
    const response = await fetch(`http://localhost:8000/users/${id}/status`); // FastAPI endpoint'iniz
    if (!response.ok) {
      throw new Error("Kullanıcı verisi çekilemedi!");
    }
    const data = await response.json();
    return { data };
  } catch (error) {
    console.error("API Hatası:", error);
    return {
      data: { total_transactions: 0, fraud_count: 0, transactions: [] }
    };
  }
};
export default function App() {
  const [transactions, setTransactions] = useState([]);
  const [alerts, setAlerts] = useState([]);
  const [selectedUser, setSelectedUser] = useState(null);
  const [userData, setUserData] = useState(null);

  useEffect(() => {
    const fetchData = () => {
      getTransactions().then(res => {
        if (res && res.data) {
          setTransactions(res.data);
        }
      });
    };

    fetchData();
    const interval = setInterval(fetchData, 3000);

    // Fake alert stream
    const alertInterval = setInterval(() => {
      if (Math.random() > 0.7) {
        setAlerts(prev => [
          {
            user_id: Math.floor(Math.random() * 10),
            message: "Şüpheli işlem tespit edildi"
          },
          ...prev
        ]);
      }
    }, 4000);

    return () => {
      clearInterval(interval);
      clearInterval(alertInterval);
    };
  }, []);

  const openUser = (id) => {
    getUserStatus(id).then(res => {
      if (res && res.data) {
        setUserData(res.data);
        setSelectedUser(id);
      }
    });
  };

  const fraudCount = Array.isArray(transactions) 
    ? transactions.filter(t => t.status === "FRAUD").length 
    : 0;

  return (
    <div className="min-h-screen bg-slate-50 text-slate-800 p-4 md:p-6">
      {/* HEADER */}
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-xl font-semibold">Fraud Detection Dashboard</h1>
        <span className="text-sm text-green-600">● Sistem Aktif</span>
      </div>

      {/* KPI */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-6">
        <KPI label="Toplam İşlem" value={transactions.length} />
        <KPI label="Fraud" value={fraudCount} />
        <KPI
          label="Oran"
          value={`%${((fraudCount / (transactions.length || 1)) * 100).toFixed(1)}`}
        />
        <KPI label="Alert" value={alerts.length} />
      </div>

      {/* GRID */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
        {/* TABLE */}
        <div className="lg:col-span-8">
          <div className="bg-white border rounded-xl overflow-hidden">
            <table className="w-full text-sm">
              <thead className="bg-slate-100">
                <tr>
                  <th className="p-3 text-left">User</th>
                  <th className="p-3">Amount</th>
                  <th className="p-3">Status</th>
                  <th className="p-3">Time</th>
                </tr>
              </thead>
              <tbody>
                {Array.isArray(transactions) && transactions.map((t, i) => (
                  <tr key={i} className="border-t hover:bg-slate-50">
                    <td
                      className="p-3 text-indigo-600 cursor-pointer"
                      onClick={() => openUser(t.user_id)}
                    >
                      {t.user_id}
                    </td>
                    <td className="p-3">{t.amount}₺</td>
                    <td className="p-3">
                      {t.status === "FRAUD" ? (
                        <span className="text-red-600 font-medium">Fraud</span>
                      ) : (
                        <span className="text-green-600">OK</span>
                      )}
                    </td>
                    <td className="p-3 text-slate-500">
                      {new Date(t.timestamp).toLocaleTimeString()}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>

        {/* RIGHT PANEL */}
        <div className="lg:col-span-4 space-y-6">
          {/* ALERT PANEL */}
          <div className="bg-white border rounded-xl p-4">
            <h2 className="font-semibold mb-3">Anlık Uyarılar</h2>
            <div className="space-y-2 max-h-[250px] overflow-y-auto">
              {alerts.length > 0 ? (
                alerts.map((a, i) => (
                  <div key={i} className="bg-red-50 border border-red-200 p-2 rounded">
                    <p className="text-sm text-red-700 font-medium">
                      User {a.user_id}
                    </p>
                    <p className="text-xs text-red-600">{a.message}</p>
                  </div>
                ))
              ) : (
                <p className="text-sm text-slate-400">Alarm yok</p>
              )}
            </div>
          </div>

          {/* CHART */}
          <FraudTrendChart transactions={transactions} />
        </div>
      </div>

      {/* MODAL */}
      {selectedUser && (
        <div className="fixed inset-0 bg-black/40 flex items-center justify-center">
          <div className="bg-white rounded-xl p-6 w-full max-w-lg">
            <h2 className="text-lg font-semibold mb-4">
              Kullanıcı #{selectedUser}
            </h2>

            {userData ? (
              <>
                <div className="grid grid-cols-3 gap-3 mb-4 text-sm">
                  <div>Toplam: {userData.total_transactions}</div>
                  <div>Fraud: {userData.fraud_count}</div>
                  <div>Risk: Yüksek</div>
                </div>

                <div className="space-y-2 max-h-[200px] overflow-y-auto">
                  {Array.isArray(userData.transactions) && userData.transactions.map((t, i) => (
                    <div key={i} className="flex justify-between">
                      <span>{new Date(t.timestamp).toLocaleTimeString()}</span>
                      <span>{t.amount}₺</span>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <p>Yükleniyor...</p>
            )}

            <button
              onClick={() => setSelectedUser(null)}
              className="mt-4 text-red-500 block"
            >
              Kapat
            </button>
          </div>
        </div>
      )}
    </div>
  );
}

function KPI({ label, value }) {
  return (
    <div className="bg-white border rounded-xl p-4">
      <p className="text-sm text-slate-500">{label}</p>
      <p className="text-xl font-semibold">{value}</p>
    </div>
  );
}

function FraudTrendChart({ transactions }) {
  const safeTransactions = Array.isArray(transactions) ? transactions : [];

  return (
    <div className="bg-white border rounded-xl p-4">
      <h2 className="font-semibold mb-3">Fraud Trend</h2>
      <div className="h-[200px]">
        <ResponsiveContainer width="100%" height="100%">
          <LineChart
            data={safeTransactions.slice(-20).map(t => ({
              time: t && t.timestamp ? new Date(t.timestamp).toLocaleTimeString() : "",
              fraud: t && t.status === "FRAUD" ? 1 : 0
            }))}
          >
            <XAxis dataKey="time" />
            <YAxis />
            <Tooltip />
            <Line type="monotone" dataKey="fraud" stroke="#6366f1" />
          </LineChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}
